import{_ as t,c as a,o as s,ah as r,j as e,a as i}from"./chunks/framework.CAZQ2vdu.js";const l="/Qonnectra-docs/pr-17/images/manual/teil-a/conduit.jpg",h="/Qonnectra-docs/pr-17/images/manual/teil-a/conduit_table.jpg",o="/Qonnectra-docs/pr-17/images/manual/teil-a/conduit_add.jpg",d="/Qonnectra-docs/pr-17/videos/conduit_add.webm",c="/Qonnectra-docs/pr-17/images/manual/teil-a/conduit_properties.jpg",u="/Qonnectra-docs/pr-17/images/manual/teil-a/conduit_status.jpg",m="/Qonnectra-docs/pr-17/images/manual/teil-a/conduit_excel.jpg",g="/Qonnectra-docs/pr-17/images/manual/teil-a/conduit_attachment.jpg",v=JSON.parse('{"title":"10. Rohrverwaltung","description":"","frontmatter":{},"headers":[],"relativePath":"manual/teil-a-anwenderhandbuch/10-rohrverwaltung.md","filePath":"manual/teil-a-anwenderhandbuch/10-rohrverwaltung.md"}'),b={name:"manual/teil-a-anwenderhandbuch/10-rohrverwaltung.md"};function p(f,n,k,w,S,_){return s(),a("div",null,[...n[0]||(n[0]=[r('<h1 id="_10-rohrverwaltung" tabindex="-1">10. Rohrverwaltung <a class="header-anchor" href="#_10-rohrverwaltung" aria-label="Permalink to &quot;10. Rohrverwaltung&quot;">​</a></h1><p>Die <strong>Rohrverwaltung</strong> führt alle Rohre des ausgewählten Projekts in einer Tabelle auf. Hier legen Sie neue Rohre an, bearbeiten vorhandene, hinterlegen Anhänge und übernehmen größere Bestände aus einer Excel-Datei. Sie erreichen sie über die linke Navigationsleiste in der Gruppe „Rohr“ durch Klicken auf den Menüpunkt „Verwaltung“.</p><p><img src="'+l+'" alt="Screenshot Rohrverwaltung mit der Tabelle aller Rohre" data-zoomable="true"></p><p>Welche Rohre die Tabelle enthält, hängt von dem Projekt ab, das oben links in der Kopfzeile ausgewählt ist, siehe Abschnitt <a href="./01-erste-schritte.html#_1-3-projekt-auswahlen-und-wechseln">Projekt auswählen und wechseln</a>.</p><h2 id="_10-1-rohrliste-durchsuchen-und-filtern" tabindex="-1">10.1 Rohrliste durchsuchen und filtern <a class="header-anchor" href="#_10-1-rohrliste-durchsuchen-und-filtern" aria-label="Permalink to &quot;10.1 Rohrliste durchsuchen und filtern&quot;">​</a></h2><p>Zu jedem Rohr zeigt die Tabelle die Spalten „Name“, „Rohrtyp“, „Schutzrohr“, „Status“, „Netzebene“, „Eigentümer“, „Baufirma“, „Hersteller“, „Datum“ und „Kennzeichen“. Das Suchfeld für den gesamten Bestand steht oben neben „Rohr hinzufügen“.</p><p>Sortierung, Suche, Spaltenfilter und Seitenwechsel funktionieren wie in Abschnitt <a href="./03-wiederkehrende-bedienelemente.html#_3-1-tabellen-suche-spaltenfilter-sortierung-seitenwechsel">Tabellen</a> beschrieben.</p><p><img src="'+h+'" alt="Screenshot Rohrverwaltung mit Hervorhebung der Spaltenüberschriften und der Seitenauswahl unten rechts" data-zoomable="true"></p><h2 id="_10-2-rohr-hinzufugen" tabindex="-1">10.2 Rohr hinzufügen <a class="header-anchor" href="#_10-2-rohr-hinzufugen" aria-label="Permalink to &quot;10.2 Rohr hinzufügen&quot;">​</a></h2><p>Klicken Sie auf „Rohr hinzufügen“. Es öffnet sich ein Dialog mit denselben Angaben, die auch die Tabelle zeigt. Ausgefüllt sein müssen „Name“, „Rohrtyp“ und „Kennzeichen“; solange eines dieser Felder leer ist, lässt sich der Dialog nicht speichern. Der Name muss innerhalb des Projekts eindeutig sein.</p><p><img src="'+o+'" alt="Screenshot des Dialogs „Rohr hinzufügen“ mit den Eingabefeldern für ein neues Rohr" data-zoomable="true"></p><p>Nach dem Klick auf „Speichern“ bleibt der Dialog geöffnet und behält alle eingetragenen Werte. So legen Sie mehrere gleichartige Rohre nacheinander an, indem Sie nur den Namen ändern. Über „Schließen“ verlassen Sie den Dialog. Das neue Rohr steht zunächst oben in der Tabelle; beim nächsten Laden der Seite sortiert es sich alphabetisch ein.</p>',12),e("p",null,[e("video",{src:d,controls:"",playsinline:"",preload:"metadata"},[i(" Ihr Browser unterstützt das Abspielen von HTML5-Videos nicht. Sie können die Datei "),e("a",{href:"/videos/conduit_add.webm",download:""},"herunterladen"),i(" anstelle des Videos. ")])],-1),r('<div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Die Angaben des zuletzt angelegten Rohrs bleiben erhalten und stehen beim nächsten Öffnen des Dialogs wieder im Formular – auch nach einem Neustart des Browsers.</p></div><p>Aus dem gewählten Rohrtyp entstehen dabei zugleich die Mikrorohre des Rohrs, siehe Abschnitt <a href="#_10-4-mikrorohre-eines-rohrs">Mikrorohre eines Rohrs</a>.</p><h2 id="_10-3-eigenschaften-bearbeiten" tabindex="-1">10.3 Eigenschaften bearbeiten <a class="header-anchor" href="#_10-3-eigenschaften-bearbeiten" aria-label="Permalink to &quot;10.3 Eigenschaften bearbeiten&quot;">​</a></h2><p>Klicken Sie ein Rohr in der Tabelle an, öffnet sich rechts die Info-Box mit dem Namen des Rohrs als Überschrift. An ihrem linken Rand stehen die drei Reiter „Eigenschaften“, „Status“ und „Anhänge“ untereinander. Sie verhält sich wie in Abschnitt <a href="./03-wiederkehrende-bedienelemente.html#_3-6-die-info-box-mit-ihren-reitern">Die Info-Box</a> beschrieben.</p><p>Im Reiter „Eigenschaften“ ändern Sie die Angaben des ausgewählten Rohrs. Die Schaltflächen „Speichern“ und „Rohr löschen“ liegen am unteren Rand der Info-Box und bleiben dort stehen; für die letzten Felder des Formulars scrollen Sie in ihr nach unten.</p><p><img src="'+c+'" alt="Screenshot Rohrverwaltung mit Hervorhebung der Info-Box zum Bearbeiten eines Rohrs im Reiter „Eigenschaften“" data-zoomable="true"></p><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Die Auswahlfelder – „Rohrtyp“, „Status“, „Netzebene“, „Eigentümer“, „Baufirma“, „Hersteller“ und „Kennzeichen“ – sind beim Öffnen leer, auch wenn das Rohr dort Werte hat. Die aktuellen Werte lesen Sie in der Tabelle ab. Ein leeres Auswahlfeld löscht beim Speichern nichts: Überschrieben wird nur, was Sie tatsächlich auswählen.</p></div><div class="danger custom-block"><p class="custom-block-title">Achtung</p><p>Speichern Sie Ihre Änderungen, bevor Sie ein anderes Rohr aus der Tabelle auswählen. Andernfalls gehen sie ohne Warnung verloren.</p></div><h2 id="_10-4-mikrorohre-eines-rohrs" tabindex="-1">10.4 Mikrorohre eines Rohrs <a class="header-anchor" href="#_10-4-mikrorohre-eines-rohrs" aria-label="Permalink to &quot;10.4 Mikrorohre eines Rohrs&quot;">​</a></h2><p>Der Reiter „Status“ listet die <strong>Mikrorohre</strong> des Rohrs auf, mit den Spalten „#“, „Farbe“, „Adresse“ (des angeschlossenen Netzknotens), „Kabel“ und „Status“. Anzahl und Farben gibt der Rohrtyp vor; ändern lassen sie sich hier nicht.</p><p><img src="'+u+'" alt="Screenshot Rohrverwaltung mit Hervorhebung der Info-Box im Reiter „Status“ mit der Liste der Mikrorohre" data-zoomable="true"></p><p>Der Status jedes Mikrorohrs steht auf „Intakt“, solange nichts anderes eingetragen ist. Über das Auswahlfeld in der Zeile vermerken Sie eine Störung, etwa „Defekt“. Diese Änderung wird sofort übernommen, es gibt dafür keinen „Speichern“-Button.</p><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Ändern Sie den Rohrtyp nachträglich, bleibt diese Liste unverändert, siehe Abschnitt <a href="./02-grundbegriffe-und-datenmodell.html#_2-1-trasse-rohr-und-mikrorohr">Trasse, Rohr und Mikrorohr</a>.</p></div><h2 id="_10-5-excel-import-vorlage-ablauf-fehlermeldungen" tabindex="-1">10.5 Excel-Import: Vorlage, Ablauf, Fehlermeldungen <a class="header-anchor" href="#_10-5-excel-import-vorlage-ablauf-fehlermeldungen" aria-label="Permalink to &quot;10.5 Excel-Import: Vorlage, Ablauf, Fehlermeldungen&quot;">​</a></h2><p>Oben rechts finden Sie zwei Schaltflächen für die Arbeit mit Excel-Dateien. „Vorlage“ lädt eine Excel-Datei mit den Spalten „Name“, „Typ“, „Schutzrohr“, „Status“, „Netzebene“, „Eigentümer“, „Baufirma“, „Hersteller“, „Datum“, „Projekt“ und „Kennzeichen“ herunter. „Excel Import“ öffnet die Dateiauswahl; sobald Sie eine Datei gewählt haben, startet der Import ohne weitere Rückfrage.</p><p><img src="'+m+'" alt="Screenshot Rohrverwaltung mit Hervorhebung der Schaltflächen „Excel Import“ und „Vorlage“ oben rechts" data-zoomable="true"></p><p>Für die Datei gilt:</p><ul><li>Sie muss im Format .xlsx vorliegen und darf höchstens 10 MB groß sein.</li><li>Die erste Zeile enthält die Spaltenüberschriften der Vorlage. Spalten, die dort nicht vorkommen, werden übergangen; darauf weist eine Meldung hin.</li><li>In der zweiten Zeile der Vorlage steht eine Beispielzeile. Überschreiben oder löschen Sie sie, sonst versucht der Import, sie als Rohr anzulegen.</li><li>Zu welchem Projekt ein Rohr gehört, entscheidet die Spalte „Projekt“ – nicht das Projekt, das in der Kopfzeile ausgewählt ist.</li><li>Die Werte in „Typ“, „Status“, „Netzebene“, „Eigentümer“, „Baufirma“, „Hersteller“, „Projekt“ und „Kennzeichen“ müssen in Qonnectra bereits vorhanden sein und genauso geschrieben werden wie dort.</li><li>Bleibt die Spalte „Typ“ leer, entsteht das Rohr ohne Mikrorohre.</li></ul><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Der Import prüft andere Pflichtangaben als der Dialog „Rohr hinzufügen“, der Name, Rohrtyp und Kennzeichen verlangt (siehe Abschnitt <a href="#_10-2-rohr-hinzufugen">Rohr hinzufügen</a>). Zeilenweise geprüft wird hier nur der Name; „Typ“ dürfen Sie bewusst leer lassen, wenn das Rohr keine Mikrorohre haben soll.</p></div><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>„Projekt“ und „Kennzeichen“ dürfen dagegen in keiner Zeile leer bleiben, obwohl der Import sie nicht zeilenweise prüft: Die Zeile kommt durch die Prüfung, das Speichern scheitert anschließend für die <strong>gesamte</strong> Datei. Die Meldung lautet dann „Fehler beim Speichern in die Datenbank“ und nennt keine Zeilennummer – anders als die übrigen Fehler. Prüfen Sie in diesem Fall die beiden Spalten auf leere Zellen.</p></div><div class="warning custom-block"><p class="custom-block-title">Wichtig</p><p>Der Import ist ein Alles-oder-nichts-Vorgang: Ist eine einzige Zeile fehlerhaft, wird keine einzige Zeile übernommen. Die Meldung nennt die betroffene Zeilennummer und den Grund. Zurückgewiesen werden unter anderem Zeilen ohne Namen und Namen, die es in Qonnectra bereits gibt – auch in einem anderen Projekt. Die Meldungen zu Eigentümer, Baufirma und Hersteller erscheinen auf Englisch, auch wenn die Oberfläche auf Deutsch steht.</p></div><div class="info custom-block"><p class="custom-block-title">Hinweis</p><p>Nach einem erfolgreichen Import nennt die Meldung die Anzahl der übernommenen Rohre; die Tabelle aktualisiert sich anschließend von selbst.</p></div><h2 id="_10-6-rohr-loschen" tabindex="-1">10.6 Rohr löschen <a class="header-anchor" href="#_10-6-rohr-loschen" aria-label="Permalink to &quot;10.6 Rohr löschen&quot;">​</a></h2><p>Über „Rohr löschen“ im Reiter „Eigenschaften“ entfernen Sie das Rohr; die Rückfrage bestätigen Sie mit „Löschen“. Ob Sie ein Rohr löschen dürfen, hängt von Ihren Rechten ab – fehlt die Berechtigung, erscheint eine Fehlermeldung.</p><div class="danger custom-block"><p class="custom-block-title">Achtung</p><p>Mit dem Rohr verschwinden auch seine Mikrorohre und seine Zuordnungen zu Trassensegmenten (siehe Kapitel <a href="./11-rohrzuordnung.html">Rohrzuordnung</a>). Rückgängig machen lässt sich das nicht.</p></div><h2 id="_10-7-anhange-an-einem-rohr" tabindex="-1">10.7 Anhänge an einem Rohr <a class="header-anchor" href="#_10-7-anhange-an-einem-rohr" aria-label="Permalink to &quot;10.7 Anhänge an einem Rohr&quot;">​</a></h2><p>Zu jedem Rohr können Sie Dateien ablegen, etwa Bestandspläne oder Messprotokolle. Hochladen, Herunterladen, Umbenennen und Löschen funktionieren wie in Abschnitt <a href="./03-wiederkehrende-bedienelemente.html#_3-7-anhange-hochladen-ansehen-und-loschen">Anhänge hochladen, ansehen und löschen</a> beschrieben.</p><p><img src="'+g+'" alt="Screenshot Rohrverwaltung mit Hervorhebung der Info-Box im Reiter „Anhänge“ mit einer hochgeladenen Datei" data-zoomable="true"></p>',28)])])}const z=t(b,[["render",p]]);export{v as __pageData,z as default};
